// FROZEN fixture. It represents the Node05 IS_READY output.
// It is not a live run. It holds IS data only. It has no OOS columns.
const runKey = 'b7c1e0d4a9f24c8fb3e6d5a10c72f984';
const runId = '3ad9f0c4b1e2487fa5c6d87013be92f4';
// The Hermes boundary supplies this analysis identity. A live channel replaces it.
const analysis = {
  source_run_key: runKey,
  source_run_id: runId,
  period_basis: 'IS',
  previous_hypothesis_ref: null,
  expectation_vs_actual: [
    { condition: 'drawdown band', expectation: 'max_drawdown <= 0.20', actual: 0.18, verdict: 'MET' },
    { condition: 'trade floor', expectation: 'trades >= 150', actual: 214, verdict: 'MET' }
  ],
  lessons: [
    'The 20/10 breakout keeps the drawdown inside the declared band.',
    'The exit window is the next candidate for one bounded retest.'
  ],
  worth_retesting: true,
  analysis_ref: 'hermes-analysis://research-loop/' + runKey + '/round-0',
  analysis_hash: 'a7d2f6b8c4e0193d5a6f7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e',
  proposal: {
    source_run_key: runKey,
    change_set: { hypothesis_group: 'donchian', params: { 'donchian.exit_window': 15 } }
  }
};
return [{
  json: {
    run_key: runKey,
    run_id: runId,
    round_index: 0,
    period_basis: 'IS',
    metrics_summary: { sharpe: 1.12, max_drawdown: 0.18, trades: 214, turnover: 3.4 },
    metrics_ref: 'mlflow://qlib/runs/' + runKey + '/metrics',
    evidence_refs: {
      run_manifest: 'mlflow://qlib/runs/' + runKey + '/manifest.json',
      analysis_source: 'hermes-analysis://research-loop/' + runKey + '/round-0'
    },
    applied_change_set: null,
    prior_hypothesis_ref: null,
    allowed_override_params: ['donchian.entry_window', 'donchian.exit_window', 'donchian.atr_stop_mult'],
    completed_runs: [{ round_index: 0, run_key: runKey, status: 'IS_SUCCESS' }],
    wiki_state: [],
    hermes_status: 'ok',
    hermes_raw: JSON.stringify(analysis)
  }
}];

// Node06 is the only reasoning point in this workflow. It holds the Hermes
// result. Nodes 07, 08 and 09 must not reason again.
// Boundary fixture for the Node06 Hermes task interface.
// The n8n container has no channel to the Hermes CLI, so the frozen fixture
// carries the Hermes answer as raw text. A live channel replaces this node.
const run = $input.first().json;
const state = {
  run_key: run.run_key,
  run_id: run.run_id,
  round_index: run.round_index,
  period_basis: run.period_basis,
  metrics_summary: run.metrics_summary,
  metrics_ref: run.metrics_ref,
  evidence_refs: run.evidence_refs,
  applied_change_set: run.applied_change_set,
  prior_hypothesis_ref: run.prior_hypothesis_ref,
  allowed_override_params: run.allowed_override_params,
  completed_runs: run.completed_runs,
  wiki_state: run.wiki_state
};
// A timeout or a transport error from the Hermes task is a review item.
// The workflow must not invent a prediction.
if (run.hermes_status !== 'ok') {
  return [{ json: Object.assign({}, state, { route: 'NEEDS_REVIEW', reason: 'hermes_' + run.hermes_status }) }];
}
let analysis = null;
try {
  analysis = JSON.parse(run.hermes_raw);
} catch (error) {
  analysis = null;
}
if (analysis === null || typeof analysis !== 'object' || Array.isArray(analysis)) {
  return [{ json: Object.assign({}, state, { route: 'NEEDS_REVIEW', reason: 'hermes_format_error' }) }];
}
return [{ json: Object.assign({}, state, { analysis: analysis, route: 'ANALYSIS_PENDING' }) }];

// Check the Node06 analysis contract. No LLM runs here.
const x = $input.first().json;
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
const a = x.analysis;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
const isText = (v) => typeof v === 'string' && v.length > 0;
const isHash = (v) => typeof v === 'string' && /^[a-f0-9]{64}$/.test(v);
const missing = [];
if (!isText(a.analysis_ref)) { missing.push('analysis_ref'); }
if (!isHash(a.analysis_hash)) { missing.push('analysis_hash'); }
if (!isText(a.source_run_key)) { missing.push('source_run_key'); }
if (!isText(a.source_run_id)) { missing.push('source_run_id'); }
if (!Array.isArray(a.lessons) || a.lessons.length === 0) { missing.push('lessons'); }
if (!Array.isArray(a.expectation_vs_actual) || a.expectation_vs_actual.length === 0) { missing.push('expectation_vs_actual'); }
if (typeof a.worth_retesting !== 'boolean') { missing.push('worth_retesting'); }
if (!a.proposal || typeof a.proposal !== 'object' || Array.isArray(a.proposal)) { missing.push('proposal'); }
if (missing.length > 0) {
  return stop('hermes_contract_incomplete:' + missing.join(','));
}
if (a.source_run_key !== x.run_key || a.source_run_id !== x.run_id) {
  return stop('analysis_source_run_mismatch');
}
if (a.period_basis !== 'IS' || x.period_basis !== 'IS') {
  return stop('period_basis_not_is');
}
if (x.round_index === 0) {
  // The baseline has no previous hypothesis.
  if (a.previous_hypothesis_ref !== null && a.previous_hypothesis_ref !== undefined) {
    return stop('baseline_has_prior_hypothesis');
  }
} else {
  if (!isText(a.previous_hypothesis_ref)) {
    return stop('missing_prior_hypothesis');
  }
  if (a.previous_hypothesis_ref !== x.prior_hypothesis_ref) {
    return stop('prior_hypothesis_ref_mismatch');
  }
}
return [{ json: Object.assign({}, x, { route: 'ANALYSIS_OK' }) }];

// Node07 is memory persistence only. It stores the Node06 analysis.
// It must not reason again and it must not rewrite the analysis.
// Boundary fixture for the Node07 Wiki Brain upsert.
// The Wiki Brain server is a local stdio MCP server. The n8n container cannot
// reach it, so the fixture applies the upsert contract on the frozen state.
// Contract: same run_key and same analysis_hash gives the same note_ref.
//           same run_key and a different analysis_hash gives a conflict.
const x = $input.first().json;
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
const a = x.analysis;
const derivedRef = 'quant/research-loop/' + x.run_key + '.md';
const state = Array.isArray(x.wiki_state) ? x.wiki_state : [];
const existing = state.filter((row) => row && row.run_key === x.run_key)[0] || null;
let ack;
if (existing === null) {
  ack = { status: 'ACK', action: 'CREATED', note_ref: derivedRef, run_key: x.run_key, analysis_hash: a.analysis_hash };
} else if (existing.analysis_hash === a.analysis_hash) {
  ack = { status: 'ACK', action: 'IDEMPOTENT', note_ref: existing.note_ref, run_key: x.run_key, analysis_hash: a.analysis_hash };
} else {
  ack = {
    status: 'CONFLICT',
    action: 'REJECTED',
    note_ref: existing.note_ref,
    run_key: x.run_key,
    analysis_hash: a.analysis_hash,
    existing_analysis_hash: existing.analysis_hash
  };
}
// Only the ACK is added. The analysis object passes through unchanged.
return [{ json: Object.assign({}, x, { wiki_ack: ack }) }];

// Node08 is deterministic validation only. No LLM runs here.
// No second opinion, no model review layer.
const x = $input.first().json;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
const a = x.analysis;
const ack = x.wiki_ack;
if (!ack || typeof ack !== 'object') { return stop('wiki_ack_missing'); }
if (ack.status !== 'ACK') { return stop('wiki_ack_' + ack.status); }
if (ack.run_key !== x.run_key) { return stop('wiki_ack_run_key_mismatch'); }
if (ack.analysis_hash !== a.analysis_hash) { return stop('analysis_hash_mismatch'); }
if (typeof ack.note_ref !== 'string' || ack.note_ref.length === 0) { return stop('wiki_note_ref_missing'); }
if (x.period_basis !== 'IS' || a.period_basis !== 'IS') { return stop('period_basis_not_is'); }
if (!a.proposal || a.proposal.source_run_key !== x.run_key) { return stop('proposal_source_run_mismatch'); }

// The IS-only allowlist is the primary OOS gate. A key outside the list is
// unexpected material.
const allowedTop = [
  'analysis_ref', 'analysis_hash', 'expectation_vs_actual', 'lessons',
  'period_basis', 'previous_hypothesis_ref', 'proposal', 'source_run_id',
  'source_run_key', 'worth_retesting'
];
const topKeys = Object.keys(a);
for (const key of topKeys) {
  if (allowedTop.indexOf(key) === -1) { return stop('unexpected_analysis_field:' + key); }
}
// A conservative regex is the second line of defence.
if (/(^|[^a-z])(oos|holdout|out_of_sample|out-of-sample)([^a-z]|$)/i.test(JSON.stringify(a))) {
  return stop('oos_material_in_analysis');
}
// The Wiki note holds lessons and references only. It must not copy raw orders.
const rawKeys = [];
const walk = (node) => {
  if (Array.isArray(node)) {
    node.forEach(walk);
    return;
  }
  if (node && typeof node === 'object') {
    Object.keys(node).forEach((key) => {
      rawKeys.push(key);
      walk(node[key]);
    });
  }
};
walk(a);
const rawHit = rawKeys.filter((key) => /(trades|equity|orders|fills|positions)/i.test(key));
if (rawHit.length > 0) { return stop('raw_result_material:' + rawHit.join(',')); }

// One change set only. Each parameter must be allowed upstream.
let changeSet = null;
if (a.worth_retesting === true) {
  const candidate = a.proposal.change_set;
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
    return stop('change_set_must_be_one_group');
  }
  if (a.proposal.change_sets !== undefined) { return stop('multiple_change_sets'); }
  if (candidate.hypothesis_groups !== undefined) { return stop('multiple_change_groups'); }
  const params = candidate.params;
  if (!params || typeof params !== 'object' || Array.isArray(params) || Object.keys(params).length === 0) {
    return stop('empty_change_set');
  }
  const allowed = Array.isArray(x.allowed_override_params) ? x.allowed_override_params : [];
  const names = Object.keys(params);
  for (const name of names) {
    if (allowed.indexOf(name) === -1) { return stop('override_param_not_allowed:' + name); }
  }
  const group = candidate.hypothesis_group;
  if (typeof group !== 'string' || group.length === 0 || Array.isArray(group)) {
    return stop('change_group_missing');
  }
  const families = names.map((name) => name.split('.')[0]).filter((f, i, arr) => arr.indexOf(f) === i);
  if (families.length !== 1) { return stop('params_span_multiple_groups:' + families.join(',')); }
  if (families[0] !== group) { return stop('change_group_mismatch'); }
  changeSet = candidate;
}
return [{ json: Object.assign({}, x, { change_set: changeSet, route: 'VALID' }) }];

// Node09 is deterministic routing only. It emits RETEST or FINALIZE.
// No LLM runs here.
const x = $input.first().json;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
if (x.route !== 'VALID') { return stop('upstream_route_not_valid:' + x.route); }
const rounds = Array.isArray(x.completed_runs) ? x.completed_runs : [];
if (rounds.length === 0) { return stop('completed_runs_empty'); }
if (rounds.length > 4) { return stop('completed_runs_above_cap'); }
const usedKeys = [];
for (let i = 0; i < rounds.length; i += 1) {
  const row = rounds[i];
  if (!row || row.round_index !== i) { return stop('round_series_not_contiguous'); }
  if (row.status !== 'IS_SUCCESS') { return stop('round_not_successful_is'); }
  if (typeof row.run_key !== 'string' || !/^[a-f0-9]{32}$/.test(row.run_key)) { return stop('run_key_bad_shape'); }
  if (usedKeys.indexOf(row.run_key) !== -1) { return stop('duplicate_run_key'); }
  usedKeys.push(row.run_key);
}
const head = rounds[rounds.length - 1];
if (head.run_key !== x.run_key) { return stop('current_run_not_canonical_head'); }
if (head.round_index !== x.round_index) { return stop('current_round_mismatch'); }

const a = x.analysis;
if (a.worth_retesting === true && rounds.length < 4) {
  return [{
    json: Object.assign({}, x, {
      route: 'RETEST',
      decision: {
        next_round_index: x.round_index + 1,
        next_parent_run_key: x.run_key,
        next_prior_hypothesis_ref: x.wiki_ack.note_ref,
        next_change_set: x.change_set,
        next_analysis_hash: x.wiki_ack.analysis_hash
      }
    })
  }];
}
const finalizeReason = a.worth_retesting === true ? 'ROUND_CAP_REACHED' : 'WORTH_RETESTING_FALSE';
return [{
  json: Object.assign({}, x, {
    route: 'FINALIZE',
    decision: {
      selected_run_key: x.run_key,
      selected_run_id: x.run_id,
      selected_round_index: x.round_index,
      selected_analysis_ref: a.analysis_ref,
      selected_analysis_hash: a.analysis_hash,
      selected_wiki_note_ref: x.wiki_ack.note_ref,
      period_basis: 'IS',
      finalize_reason: finalizeReason
    }
  })
}];
